function regenerateTarget(entry) {
    const sources = Array.isArray(entry.source) ? entry.source : [entry.source]
    const targetPath = path.join(ROOT, entry.target)
    const syncList = sources.join(', ')
    const syncedFromComment = `<!-- synced-from: ${syncList} — edit the source(s), not this file, then run: node scripts/syncCursorRules.mjs --fix -->`

    let output

    if (entry.mode === 'rule') {
        const body = stripFrontmatter(fs.readFileSync(path.join(ROOT, sources[0]), 'utf8'))
        const frontmatter = buildFrontmatter(entry.frontmatter)
        output = `${frontmatter}\n${syncedFromComment}\n\n${body}`
    } else if (entry.mode === 'skill') {
        const sourceContent = fs.readFileSync(path.join(ROOT, sources[0]), 'utf8')
        const description = extractFrontmatterField(sourceContent, 'description')
        if (!description) {
            throw new Error(`Skill source ${sources[0]} is missing a 'description' field in its frontmatter`)
        }
        const body = stripFrontmatter(sourceContent)
        const frontmatter = buildFrontmatter({
            description,
            globs: entry.frontmatter?.globs ?? '',
            alwaysApply: entry.frontmatter?.alwaysApply ?? false
        })
        output = `${frontmatter}\n${syncedFromComment}\n\n${body}`
    } else if (entry.mode === 'compile') {
        const parts = sources.map((s) => {
            const body = stripFrontmatter(fs.readFileSync(path.join(ROOT, s), 'utf8')).trim()
            return `<!-- from: ${s} -->\n\n${body}`
        })
        const title = entry.title ? `# ${entry.title}\n\n` : ''
        output = `${syncedFromComment}\n\n${title}${parts.join('\n\n---\n\n')}\n`
    } else {
        throw new Error(`Unknown mode '${entry.mode}' for target ${entry.target}`)
    }

