const { test, expect } = require('@playwright/test');
const { ListMenuPage } = require('../../../../support/pages/ListMenuPage');
const sitePrefixes = require('../../../../fixtures/sitePrefixes');

const TAGS = ['@SFCC-751', '@homepage', '@p1', '@zephyr:SFCC-T285'];
const ALL_PREFIXES = Object.values(sitePrefixes)
  .map((site) => site.urlPrefix)
  .filter(Boolean);

test.describe("Header navigation links carry the site's URL prefix", () => {
  for (const [siteKey, { urlPrefix }] of Object.entries(sitePrefixes)) {
    test(`Header navigation links carry the site's URL prefix on ${siteKey}`, { tag: TAGS }, async ({ page }) => {
      const listMenu = new ListMenuPage(page);
      await listMenu.goToSite(urlPrefix);

      const hrefs = await listMenu.getNavLinkHrefs();
      expect(hrefs.length).toBeGreaterThan(0);

      for (const href of hrefs) {
        if (urlPrefix) {
          // Some nav items render an extra wrapper link to the bare site
          // root (e.g. /us, no trailing slash — a dropdown-chevron target),
          // alongside the real /us/category/... link. Both are within-site,
          // which is what this test actually checks — reject only a href
          // that starts with the prefix but has no separator after it
          // (e.g. /usable would wrongly pass a plain startsWith(prefix)).
          expect(href === urlPrefix || href.startsWith(`${urlPrefix}/`)).toBe(true);
        } else {
          // au is root-prefixed — its links must not carry any other site's prefix
          expect(ALL_PREFIXES.some((otherPrefix) => href === otherPrefix || href.startsWith(`${otherPrefix}/`))).toBe(
            false,
          );
        }
      }
    });
  }
});

